// cnn_ref.cpp — CNN reference in C++ double precision (see cnn_ref.h)
//
// Part of VELA — Vision Edge Learning Accelerator
// Phase 2b: CNN accelerator (Vitis HLS)

#include "cnn_ref.h"

#include <cmath>
#include <cstring>

#include "cnn_weights.h"   // generated by tools/gen_weights_header.py

namespace {

// Conv 3x3, "same" padding (out-of-image inputs are 0), plus bias.
template <int CIN, int COUT, int H, int W>
void conv3x3_same(const double in[CIN][H][W], const CNN_WEIGHT_T w[COUT][CIN][K][K],
                  const CNN_WEIGHT_T b[COUT], double out[COUT][H][W]) {
    for (int co = 0; co < COUT; co++)
        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++) {
                double acc = b[co];
                for (int ci = 0; ci < CIN; ci++)
                    for (int m = 0; m < K; m++)
                        for (int n = 0; n < K; n++) {
                            const int y = i + m - K / 2;
                            const int x = j + n - K / 2;
                            if (y >= 0 && y < H && x >= 0 && x < W)
                                acc += in[ci][y][x] * w[co][ci][m][n];
                        }
                out[co][i][j] = acc;
            }
}

template <int C, int H, int W>
void relu(const double in[C][H][W], double out[C][H][W]) {
    for (int c = 0; c < C; c++)
        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                out[c][i][j] = in[c][i][j] > 0.0 ? in[c][i][j] : 0.0;
}

// Maxpool 3x3, stride 2, TensorFlow SAME padding: the padding is added at the
// bottom/right only (pad_top = pad_left = 0 for these sizes), so the window
// starts at 2i and positions past the edge are simply skipped.
template <int C, int H, int W, int HO, int WO>
void maxpool_same(const double in[C][H][W], double out[C][HO][WO]) {
    for (int c = 0; c < C; c++)
        for (int i = 0; i < HO; i++)
            for (int j = 0; j < WO; j++) {
                double m = -INFINITY;
                for (int u = 0; u < POOL; u++)
                    for (int v = 0; v < POOL; v++) {
                        const int y = i * POOL_STRIDE + u;
                        const int x = j * POOL_STRIDE + v;
                        if (y < H && x < W && in[c][y][x] > m)
                            m = in[c][y][x];
                    }
                out[c][i][j] = m;
            }
}

}  // namespace

int cnn_forward_ref(const double image[IMG_C][IMG_H][IMG_W],
                    double logits[FC_OUT], double probs[FC_OUT],
                    CnnTrace *trace) {
    static CnnTrace t;   // large buffers: static, not on the stack
    static double act1[C1][H1][W1], act2[C2][H2][W2], act3[C3][H3][W3];

    // Block 1
    conv3x3_same<IMG_C, C1, H1, W1>(image, CONV1_W, CONV1_B, t.conv1);
    relu<C1, H1, W1>(t.conv1, act1);
    maxpool_same<C1, H1, W1, P1H, P1W>(act1, t.pool1);

    // Block 2
    conv3x3_same<C1, C2, H2, W2>(t.pool1, CONV2_W, CONV2_B, t.conv2);
    relu<C2, H2, W2>(t.conv2, act2);
    maxpool_same<C2, H2, W2, P2H, P2W>(act2, t.pool2);

    // Block 3
    conv3x3_same<C2, C3, H3, W3>(t.pool2, CONV3_W, CONV3_B, t.conv3);
    relu<C3, H3, W3>(t.conv3, act3);
    maxpool_same<C3, H3, W3, P3H, P3W>(act3, t.pool3);

    // Flatten in HWC order (order of the trained FC weights)
    for (int h = 0; h < P3H; h++)
        for (int w = 0; w < P3W; w++)
            for (int c = 0; c < C3; c++)
                t.vec[(h * P3W + w) * C3 + c] = t.pool3[c][h][w];

    // Fully connected
    for (int o = 0; o < FC_OUT; o++) {
        double acc = FC_B[o];
        for (int k = 0; k < FC_IN; k++)
            acc += FC_W[o][k] * t.vec[k];
        logits[o] = acc;
    }

    // Softmax (max subtracted for numerical stability) and argmax
    int pred = 0;
    for (int o = 1; o < FC_OUT; o++)
        if (logits[o] > logits[pred]) pred = o;
    double sum = 0.0;
    for (int o = 0; o < FC_OUT; o++) {
        probs[o] = std::exp(logits[o] - logits[pred]);
        sum += probs[o];
    }
    for (int o = 0; o < FC_OUT; o++)
        probs[o] /= sum;

    if (trace)
        std::memcpy(trace, &t, sizeof(CnnTrace));
    return pred;
}
